<?php
if(!defined('ABSPATH')){exit;}if(!current_user_can(SPF_Roles::INVOICES)&&!current_user_can('manage_options')){wp_die(esc_html__('No tienes permisos para gestionar el área fiscal.','sistema-para-farmacias'));}
global $wpdb;$docs=SPF_Database::table('invoices');$sales=SPF_Database::table('sales');$customers=SPF_Database::table('customers');$adapter=SPF_Fiscal_Manager::active_adapter();$issuer=SPF_Fiscal_Settings::issuer();$notice=SPF_Fiscal_Manager::consume_notice();$internal_labels=SPF_Documents::statuses();$fiscal_labels=SPF_Documents::fiscal_statuses();$rows=$wpdb->get_results("SELECT i.*,s.sale_number,s.total,s.created_at sale_date,c.name customer_name,c.business_name,c.document_number customer_document_number FROM $docs i LEFT JOIN $sales s ON s.id=i.sale_id LEFT JOIN $customers c ON c.id=s.customer_id ORDER BY i.id DESC LIMIT 200",ARRAY_A);?>
<div class="wrap spf-wrap"><h1><?php esc_html_e('Fiscal','sistema-para-farmacias'); ?></h1>
<?php if($notice): ?><div class="notice notice-<?php echo esc_attr($notice['type']==='error'?'error':'success'); ?> is-dismissible"><p><?php echo esc_html($notice['message']); ?></p></div><?php endif; ?>
<div class="spf-panel"><h2><?php esc_html_e('Preflight fiscal','sistema-para-farmacias'); ?></h2><p><?php esc_html_e('Esta pantalla valida el comprobante con el adaptador del país y genera un XML preliminar. No firma, no transmite y no puede marcar un comprobante como aceptado por la autoridad fiscal.','sistema-para-farmacias'); ?></p><div class="spf-config-summary"><span><strong><?php esc_html_e('País','sistema-para-farmacias'); ?></strong><?php echo esc_html(SPF_Config::get('name',SPF_Config::country_code())); ?></span><span><strong><?php esc_html_e('Adaptador','sistema-para-farmacias'); ?></strong><?php echo esc_html($adapter?$adapter->code():__('No disponible','sistema-para-farmacias')); ?></span><span><strong><?php esc_html_e('Emisor','sistema-para-farmacias'); ?></strong><?php echo esc_html($issuer['legal_name']?:__('Sin configurar','sistema-para-farmacias')); ?></span></div><?php if(!$issuer['tax_id']||!$issuer['legal_name']||!$issuer['address']): ?><p class="spf-message error"><?php esc_html_e('Completa primero la identidad fiscal del emisor en Configuración.','sistema-para-farmacias'); ?> <a href="<?php echo esc_url(admin_url('admin.php?page=spf-settings')); ?>"><?php esc_html_e('Ir a Configuración','sistema-para-farmacias'); ?></a></p><?php endif; ?></div>
<div class="spf-panel"><div class="spf-table-scroll spf-table-wide"><table class="widefat striped"><thead><tr><th><?php esc_html_e('Comprobante','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Venta','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Cliente','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Total','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Estado interno','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Estado fiscal','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Adaptador','sistema-para-farmacias'); ?></th><th></th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="8"><?php esc_html_e('No hay comprobantes.','sistema-para-farmacias'); ?></td></tr><?php endif; ?><?php foreach($rows as $row): $internal=sanitize_key($row['internal_status']?:$row['sunat_status']);$fiscal=sanitize_key($row['fiscal_status']?:'not_sent'); ?><tr><td><strong><?php echo esc_html($row['serie'].'-'.$row['correlative']); ?></strong><br><small><?php echo esc_html($row['document_type']); ?></small></td><td><?php echo esc_html($row['sale_number']); ?><br><small><?php echo esc_html($row['sale_date']); ?></small></td><td><?php echo esc_html($row['business_name']?:$row['customer_name']?:'—'); ?><br><small><?php echo esc_html($row['customer_document_number']); ?></small></td><td><?php echo esc_html(SPF_Config::money($row['total'])); ?></td><td><?php echo esc_html($internal_labels[$internal]??$internal); ?></td><td><?php echo esc_html($fiscal_labels[$fiscal]??$fiscal); ?></td><td><?php echo esc_html($row['fiscal_adapter']?:($adapter?$adapter->code():'—')); ?></td><td><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><?php wp_nonce_field('spf_prepare_fiscal_document'); ?><input type="hidden" name="action" value="spf_prepare_fiscal_document"><input type="hidden" name="document_id" value="<?php echo esc_attr($row['id']); ?>"><button class="button button-primary" <?php disabled(!$adapter); ?>><?php esc_html_e('Ejecutar preflight','sistema-para-farmacias'); ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div>
